<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { merchantQueue, reviewMerchant, reviewQualification, merchantHistory, getMerchantState, changeMerchantState, type ReviewRecord, type MerchantState } from './api'
import { statusLabels, categoryLabels, type MerchantApplication } from '../campus-merchant/workflow-api'
import type { DownloadTicket } from '../campus-file/api'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
const status = ref('PENDING'), rows = ref<MerchantApplication[]>([]), selected = ref<MerchantApplication | null>(null), state = ref<MerchantState | null>(null), history = ref<ReviewRecord[]>([])
const page = ref(1), total = ref(0), reason = ref(''), message = ref(''), busy = ref(false), download = ref<DownloadTicket | null>(null)
async function load(next = 1) { busy.value = true; selected.value = null; state.value = null; download.value = null; reason.value = ''; message.value = ''; try { const [queue, records] = await Promise.all([merchantQueue(status.value, next), merchantHistory()]); rows.value = queue.items; page.value = queue.page; total.value = queue.total; history.value = records.items } catch (error) { message.value = error instanceof Error ? error.message : '审核列表加载失败' } finally { busy.value = false } }
onMounted(() => load())
async function choose(row: MerchantApplication) { selected.value = row; state.value = null; reason.value = ''; download.value = null; message.value = ''; if (row.merchantId) { busy.value = true; try { state.value = await getMerchantState(row.merchantId) } catch (error) { message.value = error instanceof Error ? error.message : '门店状态加载失败' } finally { busy.value = false } } }
async function sign() { if (!selected.value) return; busy.value = true; message.value = ''; try { download.value = await reviewQualification(selected.value.id) } catch (error) { message.value = error instanceof Error ? error.message : '资质暂不可访问' } finally { busy.value = false } }
async function decide(decision: string) { if (!selected.value) return; busy.value = true; message.value = ''; try { await reviewMerchant(selected.value.id, decision, reason.value.trim()); await load(page.value); message.value = '审核决定已保存。' } catch (error) { message.value = error instanceof Error ? error.message : '审核失败' } finally { busy.value = false } }
async function changeState() { if (!state.value) return; busy.value = true; message.value = ''; try { await changeMerchantState(state.value.id, state.value.version, state.value.status === 'APPROVED' ? 'SUSPENDED' : 'APPROVED', reason.value.trim()); state.value = await getMerchantState(state.value.id); message.value = '门店状态已更新。' } catch (error) { message.value = error instanceof Error ? error.message : '状态更新失败' } finally { busy.value = false } }
</script>
<template><section><RouterLink class="text-link" to="/admin">← 返回管理端</RouterLink><h1>商家入驻审核</h1><label for="applicationStatus">申请状态</label><select id="applicationStatus" v-model="status" :disabled="busy" @change="load()"><option value="PENDING">待审核</option><option value="APPROVED">已通过</option><option value="REJECTED">已驳回</option></select>
  <p v-if="message" role="status">{{ message }}</p><div class="review-layout"><section><p v-if="!busy && !rows.length" class="muted">当前状态暂无申请。</p><article v-for="row in rows" :key="row.id" class="review-record"><h2>{{ row.name }}</h2><p>{{ row.schoolName }} · {{ statusLabels[row.status] }}</p><button class="secondary" :disabled="busy" @click="choose(row)">查看申请</button></article><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="load" /></section>
  <article v-if="selected"><h2>{{ selected.name }}</h2><dl><dt>申请人编号</dt><dd>{{ selected.applicantId }}</dd><dt>分类</dt><dd>{{ categoryLabels[selected.category] ?? selected.category }}</dd><dt>地址</dt><dd>{{ selected.address }}</dd><dt>门店介绍</dt><dd>{{ selected.description || '暂无' }}</dd></dl><button class="secondary spaced" :disabled="busy" @click="sign">获取申请资质凭据</button><p v-if="download"><a class="text-link" :href="download.url" target="_blank" rel="noopener noreferrer">查看私有资质</a> · 有效至 {{ new Date(download.expiresAt).toLocaleTimeString() }}</p>
    <p v-if="selected.reviewReason">审核意见：{{ selected.reviewReason }}</p>
    <label v-if="selected.status === 'PENDING' || state" for="merchantReviewReason">处理原因</label><textarea v-if="selected.status === 'PENDING' || state" id="merchantReviewReason" v-model="reason" maxlength="255" rows="3" :disabled="busy" />
    <div v-if="selected.status === 'PENDING'" class="button-row"><button :disabled="busy || !reason.trim()" @click="decide('APPROVED')">通过入驻</button><button class="secondary" :disabled="busy || !reason.trim()" @click="decide('REJECTED')">驳回入驻</button></div>
    <section v-if="state"><p>门店当前状态：{{ statusLabels[state.status] ?? state.status }} · 版本 {{ state.version }}</p><button :disabled="busy || !reason.trim()" @click="changeState">{{ state.status === 'APPROVED' ? '暂停门店' : '恢复门店' }}</button></section>
  </article></div><h2 class="spaced">最近审核历史</h2><div class="table-scroll"><table><thead><tr><th>时间</th><th>申请编号</th><th>审核员</th><th>决定</th><th>原因</th></tr></thead><tbody><tr v-for="record in history" :key="record.id"><td>{{ new Date(record.createdAt).toLocaleString() }}</td><td>{{ record.resourceId }}</td><td>{{ record.reviewerId }}</td><td>{{ statusLabels[record.decision] ?? record.decision }}</td><td>{{ record.reason }}</td></tr></tbody></table></div></section></template>
